	@Test
	void orderedRootAccessUsesMeasuredIndexOrUnknownAdjacencyCeiling() throws Exception {
		LmdbStore store = storeWithDirectAdjacency(directory.resolve("ordered-roots"), true);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			ValueFactory values = repository.getValueFactory();
			IRI subject = values.createIRI("urn:work-cost:ordered-root-subject");
			seedPredicateRow(repository, values, subject, 0, PREDICATE_COUNT);
			assertThat(store.awaitDirectAdjacencyReady(60, java.util.concurrent.TimeUnit.SECONDS))
					.as(store.getDirectAdjacencyReadinessDescription())
					.isTrue();

			for (StatementOrder order : List.of(StatementOrder.S, StatementOrder.O)) {
				try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
					NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
					NativeLmdbQuerySource.IndexAccessProfile profile = source.indexAccessProfile();
					PatternPlan pattern = new PatternPlan(Term.slot(0), Term.slot(1), Term.slot(2), Term.slot(3),
							ContextConstraint.UNRESTRICTED, false, order, "", null, profile.entries(), profile);
					RowState row = new RowState(source, NativeSlotLayout.empty(), EmptyBindingSet.getInstance());
					LmdbNativeWork quote = pattern.estimateWork(row, 0L);
					SourceMeasurements measurements = new SourceMeasurements();
					long rows = 0L;
					try (RecordIterator cursor = source.statements(order, NativeLmdbQuerySource.UNKNOWN_ID,
							NativeLmdbQuerySource.UNKNOWN_ID, NativeLmdbQuerySource.UNKNOWN_ID,
							NativeLmdbQuerySource.UNKNOWN_ID, measurements)) {
						while (cursor.next() != null) {
							rows++;
						}
					}
					assertThat(rows).isEqualTo(PREDICATE_COUNT);
					assertThat(measurements.selected).isNotEmpty();
					String selected = String.join("\n", measurements.selected);
					if (selected.contains("source: IN_MEMORY_ADJACENCY")) {
						double candidateUpper = measurements.adjacencyCandidateUpper();
						assertThat(Double.isInfinite(quote.high()) || quote.high() >= candidateUpper)
								.as("selected ordered adjacency must retain its sort-capable ceiling; order=%s, quote=%s, "
										+ "candidate=%s, access=%s", order, quote, measurements.candidates, selected)
								.isTrue();
					} else {
						assertThat(quote.high())
								.as("selected indexed root work is covered; order=%s, quote=%s, access=%s, scans=%s",
										order, quote, selected, measurements.scans)
								.isGreaterThanOrEqualTo(LmdbNativeWork.SEEK + rows);
					}
				}
			}
		} finally {
			repository.shutDown();
		}
	}

