					PatternPlan rhs = pattern(Term.slot(0), Term.constant(predicateId), Term.slot(1), Term.unbound(),
							profile.entries(), profile);
					LeftJoinPlan optional = new LeftJoinPlan(SingletonPlan.INSTANCE, rhs, null, false,
							new int[] { 1 });
					NativeSlotLayout layout = new NativeSlotLayout(Map.of("x", 0, "v", 1), null);
					layout.freeze(List.of("x", "v"));
